SELECT CASE WHEN sqft >= 16340 THEN 'high' WHEN sqft >= 6183 THEN 'mid' ELSE 'low' END AS sqft_bucket, CASE WHEN city IN ('London', 'New York') THEN 'tier_1' ELSE 'other' END AS city_group, MIN(opened_date) AS min_opened_date FROM stores GROUP BY CASE WHEN sqft >= 16340 THEN 'high' WHEN sqft >= 6183 THEN 'mid' ELSE 'low' END, CASE WHEN city IN ('London', 'New York') THEN 'tier_1' ELSE 'other' END;
